// Signs a request to Convex: HMAC-SHA256 over "<timestamp>.<purpose>.<body>".
// The secret comes from the n8n environment (docker-compose / .env), never from this workflow.
const crypto = require('crypto');
function signFor(purpose, body) {
  const secret = $env.N8N_TO_CONVEX_SECRET;
  if (!secret || secret.length < 32) throw new Error('N8N_TO_CONVEX_SECRET is not set in the n8n environment');
  const timestamp = String(Math.floor(Date.now() / 1000));
  const signature = 'v1=' + crypto.createHmac('sha256', secret).update(`${timestamp}.${purpose}.${body}`).digest('hex');
  return { timestamp, signature, body };
}

// Runs when workflow 1 or 2 fails (after its own retries). Records the failure in
// Convex — shown in red on LendLoop's Admin page — and emails the admin.
const { execution = {}, workflow = {} } = $input.first().json;
const failure = {
  workflow: String(workflow.name || 'Unknown workflow').slice(0, 200),
  node: execution.error && execution.error.node ? String(execution.error.node.name || '').slice(0, 200) : (execution.lastNodeExecuted || undefined),
  // A Stop-and-Error node's own text lands in `messages`; other node errors put a
  // headline in `message` and the detail (e.g. an HTTP body) in `description`.
  message: (() => {
    const e = execution.error || {};
    const own = Array.isArray(e.messages) ? e.messages.filter(Boolean) : [];
    const parts = own.length ? own : [e.message, e.description];
    return parts.filter((v, i, a) => v && a.indexOf(v) === i).join(' — ').slice(0, 1500) || 'No error message';
  })(),
  executionId: String(execution.id || `unsaved-${Date.now()}`),
};
const app = ($env.APP_URL || 'http://localhost:3000').replace(/\/$/, '');
return [{
  json: {
    ...signFor('workflow-failure', JSON.stringify(failure)),
    to: $env.ADMIN_ALERT_EMAIL,
    subject: `LendLoop automation failed: ${failure.workflow}`,
    text: `"${failure.workflow}" failed${failure.node ? ` at "${failure.node}"` : ''}.\n\n${failure.message}\n\nn8n execution: ${execution.url || failure.executionId}\nLendLoop admin: ${app}/admin`,
  },
}];
